import xml.etree.ElementTree as ET
import csv

def task_func(xml_content, output_csv_path):
    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as e:
        raise ET.ParseError(f"Error parsing XML: {e}")

    try:
        with open(output_csv_path, 'w', newline='', encoding='utf-8') as csv_file:
            writer = csv.writer(csv_file)
            def write_element(elem):
                writer.writerow([elem.tag, elem.text if elem.text is not None else ''])
                for child in elem:
                    write_element(child)
            write_element(root)
    except IOError as e:
        raise IOError(f"Error writing to CSV file: {e}")
